// @ts-nocheck — this is the wrangler entry, not part of the Next app. It
// statically imports `../.open-next/worker.js`, which OpenNext only emits
// during `opennextjs-cloudflare build` (after `next build`). That module
// therefore can't exist at type-check time, so type-checking this glue
// file is impossible by construction; wrangler resolves the import at
// bundle time, once the file has been generated.
/**
 * @packageDocumentation
 *
 * Production Worker entry point.
 *
 * The Next.js handler is generated by OpenNext into `.open-next/worker.js`.
 * This file forwards `fetch` to it and adds the site's response headers
 * (see `lib/http/headers.ts`). It is a thin wrapper (rather than pointing
 * `wrangler.jsonc` straight at the generated file) so Worker-level additions —
 * cron handlers, Workflow exports, Durable Objects — have an obvious home.
 *
 * Deployment glue:
 *
 *   1. `wrangler.jsonc` -> `main` set to this file (`src/worker.ts`).
 *   2. `next build && opennextjs-cloudflare build` produces
 *      `.open-next/worker.js`.
 *   3. `wrangler deploy` bundles this file.
 */

import openNextHandler from '../.open-next/worker.js';
import { applyResponseHeaders } from './lib/http/headers';

const handler: ExportedHandler<CloudflareEnv> = {
  /**
   * Forwarded to OpenNext's Next.js handler, with the site's security and cache
   * headers added to whatever comes back.
   */
  async fetch(request, env, ctx) {
    const response = await (
      openNextHandler as ExportedHandler<CloudflareEnv>
    ).fetch!(request, env, ctx);
    return applyResponseHeaders(request, response);
  },
};

export default handler;
